fn solve(r: i8, g: i8, b: i8) -> i8 {
    // Cast to a larger integer type to avoid overflow when summing.
    let r = r as i32;
    let g = g as i32;
    let b = b as i32;

    // Total items
    let total = r + g + b;
    // You can't form more tables than total/3 (each table uses 3 items).
    let max_by_total = total / 3;
    // You also can't form more tables than the sum of any two colors,
    // since each table must include at least one item not of the third color.
    let max_by_pairs = (r + g).min(r + b).min(g + b);

    // The answer is the minimum of these two constraints.
    let ans = max_by_total.min(max_by_pairs);

    // It's guaranteed that ans fits in i8 under the problem constraints.
    ans as i8
}

